/// Returns true if `n` is a power of two (and positive).
/// (Included because it appears in the problem statement.)
pub fn is_2_pow(n: i128) -> bool {
    if n <= 0 {
        return false;
    }
    let mut v = n as u128;
    (v & (v - 1)) == 0
}

/// Lower-bound helper on a sorted range `a[lo..hi)`.
/// Returns `k` in `[lo, hi]` such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());

    let mut l = lo;
    let mut r = hi;
    while l < r {
        let m = l + (r - l) / 2;
        if a[m] < x {
            l = m + 1;
        } else {
            r = m;
        }
    }
    l
}

/// Lower-bound of `x` within the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and that `a[0..1000]` is sorted nondecreasing.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}